## 3. Implementación de Código Determinista

### Componente Refactorizado: `Keypad.tsx` (Dark Glassmorphism V8)

```tsx
import React from 'react';

interface KeypadProps {
  onKeyPress: (value: string) => void;
  onClear: () => void;
  onDelete: () => void;
  onSubmit: () => void;
  disabled?: boolean;
}

export const Keypad: React.FC<KeypadProps> = ({
  onKeyPress,
  onClear,
  onDelete,
  onSubmit,
  disabled = false,
}) => {
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '.', '0', '00'];

  return (
    <div className="grid grid-cols-3 gap-2.5 p-3 bg-slate-900/40 backdrop-blur-xl border border-white/10 rounded-2xl shadow-2xl">
      {keys.map((key) => (
        <button
          key={key}
          type="button"
          disabled={disabled}
          onClick={() => onKeyPress(key)}
          className="h-14 flex items-center justify-center text-xl font-semibold font-mono text-slate-100 
                     bg-slate-800/40 hover:bg-slate-700/60 active:bg-slate-600/60 
                     border border-white/5 hover:border-white/10 rounded-xl
                     shadow-[0_4px_12px_rgba(0,0,0,0.1)] active:scale-[0.97] 
                     transition-all duration-100 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {key}
        </button>
      ))}
      <button
        type="button"
        disabled={disabled}
        onClick={onClear}
        className="h-14 flex items-center justify-center text-sm font-bold text-rose-400 
                   bg-rose-500/10 hover:bg-rose-500/20 active:bg-rose-500/30 
                   border border-rose-500/20 rounded-xl transition-all duration-100"
      >
        AC
      </button>
      <button
        type="button"
        disabled={disabled}
        onClick={onDelete}
        className="h-14 flex items-center justify-center text-sm font-bold text-amber-400 
                   bg-amber-500/10 hover:bg-amber-500/20 active:bg-amber-500/30 
                   border border-amber-500/20 rounded-xl transition-all duration-100"
      >
        ⌫
      </button>
      <button
        type="button"
        disabled={disabled}
        onClick={onSubmit}
        className="col-span-3 h-14 flex items-center justify-center text-base font-bold text-emerald-300 
                   bg-emerald-500/20 hover:bg-emerald-500/30 active:bg-emerald-500/40 
                   border border-emerald-500/30 rounded-xl shadow-[0_4px_20px_rgba(16,185,129,0.2)] 
                   transition-all duration-100"
      >
        CONFIRMAR / COBRAR
      </button>
    </div>
  );
};
```

